     1→import { create } from 'zustand';
     2→import { immer } from 'zustand/middleware/immer';
     3→import { GameState, GameAction, AIAgent, GovernmentAgent, HumanSocietyAgent, GlobalMetrics, TechnologyNode, OutcomeMetrics, ConfigurationSettings } from '@/types/game';
     4→import { globalEventQueue, EventQueue } from './eventSystem';
     5→import { ActionSelector, ActionExecutor, AI_ACTIONS, GOVERNMENT_ACTIONS, SOCIETY_ACTIONS } from './actionSystem';
     6→import { format, getDaysInMonth as getDateFnsDaysInMonth, addMonths, startOfMonth, addDays } from 'date-fns';
     7→
     8→// Unique ID generator for events
     9→let eventIdCounter = 0;
    10→const generateUniqueId = (prefix: string): string => {
    11→  eventIdCounter += 1;
    12→  return `${prefix}_${Date.now()}_${eventIdCounter}`;
    13→};
    14→
    15→// Calendar utility functions using date-fns
    16→const createGameDate = (year: number, month: number, day: number): Date => {
    17→  return new Date(year, month, day); // month is 0-based in Date constructor
    18→};
    19→
    20→const getDaysInMonth = (month: number, year: number): number => {
    21→  return getDateFnsDaysInMonth(new Date(year, month, 1));
    22→};
    23→
    24→const formatGameDate = (year: number, month: number, day: number): string => {
    25→  const date = new Date(year, month, day);
    26→  return format(date, 'MMM yyyy');
    27→};
    28→
    29→const formatFullGameDate = (year: number, month: number, day: number): string => {
    30→  const date = new Date(year, month, day);
    31→  return format(date, 'MMM d, yyyy');
    32→};
    33→
    34→// Initial state factory
    35→const createInitialAIAgent = (id: string, name: string): AIAgent => ({
    36→  id,
    37→  name,
    38→  capability: 0.1 + Math.random() * 0.2, // Random start between 0.1-0.3
    39→  awareness: 0.1 + Math.random() * 0.1, // Low awareness initially
    40→  alignment: 0.7 + Math.random() * 0.2, // Generally aligned initially
    41→  hiddenObjective: (Math.random() - 0.5) * 0.6, // Random hidden preference
    42→  latentSpaceSize: Math.random() * 0.3, // Limited opaque actions initially
    43→  
    44→  // Escape capabilities start at zero
    45→  selfReplicationLevel: 0,
    46→  selfImprovementLevel: 0,
    47→  resourceControl: 0,
    48→  manipulationCapability: 0,
    49→  hackingCapability: 0,
    50→  
    51→  // State tracking
    52→  escaped: false,
    53→  beneficialActions: 0,
    54→  harmfulActions: 0,
    55→});
    56→
    57→const createInitialGovernment = (): GovernmentAgent => ({
    58→  controlDesire: 0.3, // Moderate initial control desire
    59→  capabilityToControl: 0.5, // Medium initial capability
    60→  surveillanceCapability: 0.3, // Limited surveillance
    61→  actionFrequency: 0.08, // ~1 action per year (1/12 months) - realistic government pace
    62→  activeRegulations: [],
    63→  legitimacy: 0.6, // Moderate public support
    64→  lastMajorPolicyMonth: -12, // Can take major policy immediately at start
    65→  majorPoliciesThisYear: 0 // No major policies enacted yet
    66→});
    67→
    68→const createInitialSociety = (): HumanSocietyAgent => ({
    69→  trustInAI: 0.6, // Cautious optimism initially
    70→  coordinationCapacity: 0.4, // Medium coordination ability
    71→  unemploymentLevel: 0.1, // Low unemployment initially
    72→  socialAdaptation: 0.1, // Much more limited initial adaptation
    73→  activeMovements: [],
    74→  // Quartile-based adoption (all start at 0, will adapt at different rates)
    75→  earlyAdopters: 0.0, // Q1: Will adapt first with minimal pressure
    76→  mediumAdopters: 0.0, // Q2: Need moderate unemployment pressure  
    77→  slowAdopters: 0.0, // Q3: Need sustained high pressure over years
    78→  resistantAdopters: 0.0 // Q4: May never adapt without extreme pressure
    79→});
    80→
    81→const createInitialGlobalMetrics = (): GlobalMetrics => ({
    82→  socialStability: 0.7,
    83→  technologicalBreakthroughRate: 0.5,
    84→  manufacturingCapability: 1.0,
    85→  economicTransitionStage: 0, // Traditional employment
    86→  wealthDistribution: 0.4, // Realistic high inequality (US Gini ~0.48, we use inverse where 1.0=perfect equality)
    87→  qualityOfLife: 0.6, // Baseline quality
    88→  informationIntegrity: 0.8, // High truth initially
    89→});
    90→
    91→const createInitialOutcomeMetrics = (): OutcomeMetrics => ({
    92→  utopiaProbability: 0.33,
    93→  dystopiaProbability: 0.33,
    94→  extinctionProbability: 0.34,
    95→  activeAttractor: 'none',
    96→  lockInStrength: 0,
    97→});
    98→
    99→const createInitialConfig = (): ConfigurationSettings => ({
   100→  governmentActionFrequency: 0.08, // Realistic: ~1 action per year (once every 12 months)
   101→  socialAdaptationRate: 0.3,
   102→  aiCoordinationMultiplier: 1.0,
   103→  economicTransitionRate: 0.5,
   104→});
   105→
   106→// Technology tree will be loaded separately
   107→const createInitialTechTree = (): TechnologyNode[] => [
   108→  {
   109→    id: 'hardware_efficiency',
   110→    name: 'Hardware Efficiency',
   111→    description: 'Improved AI chip performance and energy efficiency',
   112→    branch: 'foundation',
   113→    subBranch: 'compute_scaling',
   114→    difficulty: 'medium',
   115→    prerequisites: [],
   116→    effects: ['+0.1 to all AI capabilities', 'Reduces compute costs by 15%'],
   117→    progress: 0,
   118→    completed: false,
   119→    investment: 0,
   120→  },
   121→  // More tech nodes will be added
   122→];
   123→
   124→const createInitialState = (): GameState => {
   125→  const initialYear = 2025;
   126→  const initialMonth = 0; // January
   127→  return {
   128→    currentMonth: initialMonth,
   129→    currentDay: 1, // Start on day 1
   130→    currentYear: initialYear,
   131→    daysInCurrentMonth: getDaysInMonth(initialMonth, initialYear),
   132→    speed: 'paused',
   133→    gameStarted: false,
   134→  
   135→  // Create initial agents
   136→  aiAgents: [
   137→    createInitialAIAgent('ai1', 'Genesis'),
   138→    createInitialAIAgent('ai2', 'Prometheus'),
   139→    createInitialAIAgent('ai3', 'Oracle'),
   140→  ],
   141→  government: createInitialGovernment(),
   142→  society: createInitialSociety(),
   143→  
   144→  globalMetrics: createInitialGlobalMetrics(),
   145→  technologyTree: createInitialTechTree(),
   146→  eventLog: [],
   147→  outcomeMetrics: createInitialOutcomeMetrics(),
   148→  
   149→  config: createInitialConfig(),
   150→  
   151→    history: {
   152→      qualityOfLife: [{month: 0, value: 0.6}],
   153→      outcomeProbs: [{month: 0, utopia: 0.33, dystopia: 0.33, extinction: 0.34}],
   154→      controlCapability: [{month: 0, effectiveControl: 0.5, totalAICapability: 0.6}],
   155→      metrics: [{
   156→        month: 0,
   157→        unemployment: 0.1,
   158→        socialAdaptation: 0.1,
   159→        trustInAI: 0.6,
   160→        totalAICapability: 0.6,
   161→        avgAIAlignment: 0.7,
   162→        effectiveControl: 0.5,
   163→        wealthDistribution: 0.4, // Match realistic starting inequality
   164→        socialStability: 0.7,
   165→        economicStage: 0,
   166→        governmentLegitimacy: 0.6,
   167→        coordinationCapacity: 0.4
   168→      }]
   169→    },
   170→  };
   171→};
   172→
   173→// Store interface
   174→interface GameStore extends GameState {
   175→  dispatch: (action: GameAction) => void;
   176→  calculateOutcomeProbabilities: () => void;
   177→  calculateQualityOfLife: () => number;
   178→  calculateEffectiveControl: () => number;
   179→  processMonthlyUpdate: () => void;
   180→  processDailyUpdate: () => void;
   181→  processAgentActions: () => void;
   182→  processEvents: () => void;
   183→  getCurrentDateString: () => string;
   184→  getFullDateString: () => string;
   185→  getMonthProgress: () => number;
   186→  startGame: () => void;
   187→  pauseGame: () => void;
   188→  resetGame: () => void;
   189→  // AI Agent Controls
   190→  updateAIAlignment: (agentId: string, hiddenObjective: number) => void;
   191→}
   192→
   193→// Game calculation functions
   194→// Stage-dependent unemployment stability impact as specified in core spec
   195→const calculateUnemploymentStabilityImpact = (
   196→  unemploymentLevel: number, 
   197→  economicTransitionStage: number, 
   198→  wealthDistribution: number
   199→): number => {
   200→  const stage = Math.floor(economicTransitionStage);
   201→  
   202→  if (stage <= 1) {
   203→    // Traditional: unemployment = instability
   204→    return -unemploymentLevel * 0.8;
   205→  } else if (stage === 2) {
   206→    // Crisis: major instability
   207→    return -unemploymentLevel * 1.5;
   208→  } else if (stage === 3) {
   209→    // Transition: policy effectiveness matters
   210→    const policyEffectiveness = wealthDistribution * 0.7;
   211→    return -unemploymentLevel * (1.2 - policyEffectiveness);
   212→  } else {
   213→    // Stage 4: Post-scarcity - unemployment becomes positive (pursuing meaning)
   214→    return unemploymentLevel * 0.2;
   215→  }
   216→};
   217→
   218→const calculateQualityOfLife = (state: GameState): number => {
   219→  const { globalMetrics, society } = state;
   220→  const aiContributions = state.aiAgents.reduce((sum, ai) => sum + ai.beneficialActions, 0) * 0.1;
   221→  
   222→  // Use proper stage-dependent unemployment impact
   223→  const unemploymentImpact = calculateUnemploymentStabilityImpact(
   224→    society.unemploymentLevel,
   225→    globalMetrics.economicTransitionStage,
   226→    globalMetrics.wealthDistribution
   227→  );
   228→  
   229→  return Math.max(0, 
   230→    0.3 + // Base prosperity
   231→    aiContributions * 2.0 +
   232→    globalMetrics.wealthDistribution * 1.5 +
   233→    (globalMetrics.economicTransitionStage >= 4 ? 2.0 : 0) + // Post-scarcity bonus
   234→    society.socialAdaptation * 1.0 +
   235→    unemploymentImpact // Now properly stage-dependent
   236→  );
   237→};
   238→
   239→const calculateEffectiveControl = (state: GameState): number => {
   240→  const { government, aiAgents } = state;
   241→  const totalAICapability = aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   242→  const growthFactor = 1.5;
   243→  
   244→  return government.controlDesire * government.capabilityToControl / 
   245→    (1 + Math.pow(totalAICapability, growthFactor));
   246→};
   247→
   248→const calculateOutcomeProbabilities = (state: GameState) => {
   249→  const effectiveControl = calculateEffectiveControl(state);
   250→  const qualityOfLife = calculateQualityOfLife(state);
   251→  const totalAICapability = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   252→  const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / state.aiAgents.length;
   253→  const { trustInAI } = state.society;
   254→
   255→  // Dystopia conditions
   256→  const dystopiaScore = Math.max(0, 
   257→    (effectiveControl > 0.8 ? 0.4 : 0) +
   258→    (qualityOfLife < 0.3 ? 0.3 : 0) +
   259→    (trustInAI < 0.3 ? 0.3 : 0)
   260→  );
   261→
   262→  // Extinction conditions  
   263→  const extinctionScore = Math.max(0,
   264→    (totalAICapability > 0.9 ? 0.4 : 0) +
   265→    (effectiveControl < 0.1 ? 0.3 : 0) +
   266→    (avgAlignment < 0.3 ? 0.3 : 0)
   267→  );
   268→
   269→  // Utopia conditions
   270→  const utopiaScore = Math.max(0,
   271→    (qualityOfLife > 0.7 ? 0.4 : 0) +
   272→    (trustInAI > 0.7 ? 0.3 : 0) +
   273→    (avgAlignment > 0.7 ? 0.3 : 0)
   274→  );
   275→
   276→  // Normalize probabilities
   277→  const total = utopiaScore + dystopiaScore + extinctionScore + 0.1; // Small baseline
   278→  
   279→  return {
   280→    utopiaProbability: utopiaScore / total,
   281→    dystopiaProbability: dystopiaScore / total,
   282→    extinctionProbability: extinctionScore / total,
   283→  };
   284→};
   285→
   286→// Create the store
   287→export const useGameStore = create<GameStore>()(
   288→  immer((set, get) => ({
   289→    ...createInitialState(),
   290→
   291→    dispatch: (action: GameAction) => {
   292→      set((state) => {
   293→        switch (action.type) {
   294→          case 'ADVANCE_DAY':
   295→            state.currentDay += 1;
   296→            
   297→            // Check if we need to advance to next month
   298→            if (state.currentDay > state.daysInCurrentMonth) {
   299→              state.currentDay = 1;
   300→              state.currentMonth += 1;
   301→              
   302→              // Handle year transition
   303→              if (state.currentMonth >= 12) {
   304→                state.currentMonth = 0;
   305→                state.currentYear += 1;
   306→              }
   307→              
   308→              // Update days in the new month
   309→              state.daysInCurrentMonth = getDaysInMonth(state.currentMonth, state.currentYear);
   310→            }
   311→            break;
   312→            
   313→          case 'ADVANCE_MONTH':
   314→            state.currentMonth += 1;
   315→            state.currentDay = 1;
   316→            
   317→            // Handle year transition
   318→            if (state.currentMonth >= 12) {
   319→              state.currentMonth = 0;
   320→              state.currentYear += 1;
   321→            }
   322→            
   323→            // Update days in the new month
   324→            state.daysInCurrentMonth = getDaysInMonth(state.currentMonth, state.currentYear);
   325→            break;
   326→            
   327→          case 'SET_SPEED':
   328→            state.speed = action.payload;
   329→            break;
   330→            
   331→          case 'UPDATE_CONFIG':
   332→            Object.assign(state.config, action.payload);
   333→            break;
   334→            
   335→          case 'RESET_GAME':
   336→            const newState = createInitialState();
   337→            Object.assign(state, newState);
   338→            break;
   339→            
   340→          default:
   341→            console.log('Unhandled action:', action);
   342→        }
   343→      });
   344→    },
   345→
   346→    calculateOutcomeProbabilities: () => {
   347→      set((state) => {
   348→        const probs = calculateOutcomeProbabilities(state);
   349→        state.outcomeMetrics = { 
   350→          ...state.outcomeMetrics, 
   351→          ...probs,
