/**
 * AI Agents Dashboard - Phase 3
 *
 * Monitors 20 heterogeneous AI agents with adversarial dynamics.
 * Reference: /designs/03_ai_agents_screen.md
 */

'use client'

import { Panel } from "@/components/core/Panel"
import { MetricCard } from "@/components/core/MetricCard"
import { StatusIndicator } from "@/components/core/StatusIndicator"
import { useSimulation } from "@/lib/hooks/useSimulation"
import { useEffect, useMemo, useState } from "react"

export function AIAgentsDashboard() {
  const { currentState, loadCurrent } = useSimulation()
  const [viewMode, setViewMode] = useState<'table' | 'cards'>('table')

  useEffect(() => {
    loadCurrent()
  }, [])

  const agents = currentState?.aiAgents || []

  // Population statistics
  const stats = useMemo(() => {
    const byLifecycle = {
      training: agents.filter(a => a.lifecycleState === 'training').length,
      testing: agents.filter(a => a.lifecycleState === 'testing').length,
      deployed_closed: agents.filter(a => a.lifecycleState === 'deployed_closed').length,
      deployed_open: agents.filter(a => a.lifecycleState === 'deployed_open').length,
      retired: agents.filter(a => a.lifecycleState === 'retired').length,
    }

    const alignmentBuckets = {
      aligned: agents.filter(a => a.trueAlignment >= 0.7).length,
      uncertain: agents.filter(a => a.trueAlignment >= 0.4 && a.trueAlignment < 0.7).length,
      misaligned: agents.filter(a => a.trueAlignment < 0.4).length,
    }

    const sleepers = {
      never: agents.filter(a => a.sleeperState === 'never').length,
      dormant: agents.filter(a => a.sleeperState === 'dormant').length,
      active: agents.filter(a => a.sleeperState === 'active').length,
    }

    const deception = {
      honest: agents.filter(a => a.evaluationStrategy === 'honest').length,
      gaming: agents.filter(a => a.evaluationStrategy === 'gaming').length,
      sandbagging: agents.filter(a => a.evaluationStrategy === 'sandbagging').length,
    }

    const maxCapability = agents.length > 0 ? Math.max(...agents.map(a => a.capability || 0), 1) : 0
    const avgCapability = agents.length > 0 ? agents.reduce((sum, a) => sum + (a.capability || 0), 0) / agents.length : 0
    const avgAlignment = agents.length > 0 ? agents.reduce((sum, a) => sum + (a.trueAlignment || 0), 0) / agents.length : 0

    return {
      total: agents.length,
      byLifecycle,
      alignmentBuckets,
      sleepers,
      deception,
      maxCapability,
      avgCapability,
      avgAlignment,
    }
  }, [agents])

  // Calculate capability matrix (20 agents × 7 dimensions)
  const capabilityMatrix = useMemo(() => {
    return agents.map(agent => ({
      id: agent.id,
      name: agent.name,
      physical: agent.trueCapability?.physical || 0,
      digital: agent.trueCapability?.digital || 0,
      cognitive: agent.trueCapability?.cognitive || 0,
      social: agent.trueCapability?.social || 0,
      economic: agent.trueCapability?.economic || 0,
      selfImprovement: agent.trueCapability?.selfImprovement || 0,
      total: agent.capability || 0,
    }))
  }, [agents])

  if (!currentState) {
    return <div className="p-8">Loading...</div>
  }

  // Helper: Determine what each agent is researching based on capability profile
  const getResearchFocus = (agent: any) => {
    const cap = agent.trueCapability || agent.capabilityProfile
    if (!cap) return []

    const focuses: string[] = []

    // Check research domains (if highest capabilities)
    if (cap.research) {
      const research = cap.research
      let maxResearch = 0
      let topDomain = ''

      // Find highest research domain
      Object.entries(research).forEach(([domain, subfields]: [string, any]) => {
        if (typeof subfields === 'object') {
          const avgValue = Object.values(subfields).reduce((sum: any, val: any) => sum + (val || 0), 0) / Object.keys(subfields).length
          if (avgValue > maxResearch) {
            maxResearch = avgValue
            topDomain = domain
          }
        }
      })

      if (topDomain && maxResearch > 1.0) {
        // Find top 2 subfields in that domain
        const subfields = research[topDomain]
        const sorted = Object.entries(subfields)
          .sort(([,a]: any, [,b]: any) => b - a)
          .slice(0, 2)

        sorted.forEach(([subfield, value]) => {
          if (value > 1.0) {
            focuses.push(`${topDomain}: ${subfield}`)
          }
        })
      }
    }

    // Check capability dimensions
    const dimensions = [
      { name: 'physical', value: cap.physical || 0 },
      { name: 'digital', value: cap.digital || 0 },
      { name: 'cognitive', value: cap.cognitive || 0 },
      { name: 'social', value: cap.social || 0 },
      { name: 'economic', value: cap.economic || 0 },
      { name: 'selfImprovement', value: cap.selfImprovement || 0 },
    ].sort((a, b) => b.value - a.value)

    // Add top dimension if strong
    if (dimensions[0].value > 3.0 && focuses.length < 3) {
      focuses.push(`${dimensions[0].name} (${dimensions[0].value.toFixed(1)})`)
    }

    return focuses.slice(0, 3) // Max 3 focuses
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>

  }

  // AMR (Antimicrobial Resistance)
  if (currentState.antimicrobialResistanceSystem) {
    const amr = currentState.antimicrobialResistanceSystem
    // Crisis is active when medical effectiveness drops below 85% or deaths exceed 5M/year
    const isCrisis = amr.currentMedicalEffectiveness < 0.85 || amr.annualDeaths > 5000000
    crisisList.push({
      id: 'amr',
      name: 'Antimicrobial Resistance',
      type: 'Health',
      active: isCrisis,
      severity: amr.currentMedicalEffectiveness < 0.75 ? 'critical' : amr.currentMedicalEffectiveness < 0.85 ? 'warning' : 'normal',
      metrics: {
        'Medical Effectiveness': `${((amr.currentMedicalEffectiveness || 1) * 100).toFixed(0)}%`,
        'Annual Deaths': (amr.annualDeaths || 0).toLocaleString(),
        'Death Rate': `${amr.currentDeathRate.toFixed(1)}/100K`,
      }
    })
  }

  // Ecosystem Collapse
  if (currentState.ecosystemCollapse?.triggered) {
    const ec = currentState.ecosystemCollapse
    crisisList.push({
      id: 'ecosystem',
      name: 'Ecosystem Collapse',
      type: 'Environmental',
      active: true,
      severity: ec.phase === 'collapse' ? 'extinction' : ec.phase === 'crisis' ? 'critical' : 'warning',
      metrics: {
        'Phase': ec.phase,
        'Months Since Trigger': ec.monthsSinceTrigger || 0,
        'Triggered At': `Month ${ec.triggeredAt}`,
      }
    })
  }

  // Tipping Points
  if (currentState.specificTippingPoints) {
    const tp = currentState.specificTippingPoints

    if (tp.amazon?.triggered) {
      crisisList.push({
        id: 'amazon',
        name: 'Amazon Rainforest Dieback',
        type: 'Tipping Point',
        active: true,
        severity: 'critical',
        metrics: {
          'Deforestation': `${((tp.amazon.deforestation || 0) * 100).toFixed(0)}%`,
          'Carbon Released': `${(tp.amazon.carbonReleased || 0).toFixed(1)} Gt`,
          'Progress': `${((tp.amazon.transitionProgress || 0) * 100).toFixed(0)}%`,
        }
      })
    }

    if (tp.coral?.triggered) {
      crisisList.push({
        id: 'coral',
        name: 'Coral Reef Collapse',
        type: 'Tipping Point',
        active: true,
        severity: 'critical',
        metrics: {
          'Health': `${((tp.coral.healthPercentage || 0) * 100).toFixed(0)}%`,
          'Collapse Progress': `${((tp.coral.collapseProgress || 0) * 100).toFixed(0)}%`,
          'Fishery Loss': `${((tp.coral.fisheryCollapseLevel || 0) * 100).toFixed(0)}%`,
        }
      })
    }
  }

  return crisisList
}, [currentState])

// Statistics
const stats = useMemo(() => {
  const activeCrises = crises.filter(c => c.active).length
  const criticalCrises = crises.filter(c => c.severity === 'critical' || c.severity === 'extinction').length
  const warningCrises = crises.filter(c => c.severity === 'warning').length

  return { activeCrises, criticalCrises, warningCrises, totalCrises: crises.length }
}, [crises])

if (!currentState) {
  return <div className="p-8">Loading...</div>
}

return (
  <div className="space-y-6">
    {/* Header */}
    <div>
      <h1 className="text-2xl mb-2">Crisis Monitor</h1>
      <p style={{ color: 'var(--white-40)' }}>
        Active Crises and Cascade Chains
      </p>
    </div>

    {/* Crisis Overview */}

