/**
 * Simulation Worker Context
 *
 * Global singleton for managing the simulation Web Worker.
 * Ensures only ONE worker instance exists across the entire app.
 * Provides shared state to Navigation and all dashboard pages.
 *
 * Architecture:
 * - Single worker created on app mount
 * - Shared state distributed via React Context
 * - Components subscribe to updates without creating duplicate workers
 * - Proper cleanup on app unmount only
 */

'use client'

import { createContext, useContext, useEffect, useRef, useState, type ReactNode } from 'react'
import { SimulationWorkerClient, type StateDelta, type InitialStateSnapshot } from '@/lib/simulationWorkerClient'
import type { ScenarioMode } from '@/types/game'

interface SimulationWorkerContextValue {
  // Worker client (singleton)
  client: SimulationWorkerClient | null

  // Simulation state
  initialized: boolean
  running: boolean
  month: number
  day: number
  year: number
  scenario: ScenarioMode
  seed: number

  // Latest update delta (for pages that need detailed state)
  lastUpdate: StateDelta | null

  // Control functions
  init: (seed: number, scenario: ScenarioMode, speed: number) => void
  start: () => void
  pause: () => void
  step: () => void
}

const SimulationWorkerContext = createContext<SimulationWorkerContextValue | null>(null)

export function SimulationWorkerProvider({ children }: { children: ReactNode }) {
  // Use ref to ensure worker persists across re-renders
  const clientRef = useRef<SimulationWorkerClient | null>(null)

  // Shared state
  const [initialized, setInitialized] = useState(false)
  const [running, setRunning] = useState(false)
  const [month, setMonth] = useState(0)
  const [day, setDay] = useState(1)
  const [year, setYear] = useState(2025)
  const [scenario, setScenario] = useState<ScenarioMode>('historical')
  const [seed, setSeed] = useState(42000)
  const [lastUpdate, setLastUpdate] = useState<StateDelta | null>(null)

  // Create singleton worker on mount
  useEffect(() => {
    if (typeof window === 'undefined') return

    // Only create if doesn't exist
    if (!clientRef.current) {
      try {
        const client = new SimulationWorkerClient()
        clientRef.current = client

        console.log('[WorkerContext] Created singleton worker client')

        // Setup global listeners
        client.on('initialized', (snapshot: InitialStateSnapshot) => {
          console.log('[WorkerContext] Worker initialized:', snapshot)
          setInitialized(true)
          setMonth(snapshot.currentMonth)
          setScenario(snapshot.scenario)
        })

        client.on('update', (delta: StateDelta, currentMonth?: number, currentDay?: number) => {
          setLastUpdate(delta)
          if (delta.currentMonth !== undefined) {
            setMonth(delta.currentMonth)
          }
          if (delta.currentYear !== undefined) {
            setYear(delta.currentYear)
          }
          if (currentDay !== undefined) {
            setDay(currentDay)
          }
        })

        client.on('dayUpdate', (currentDay: number) => {
          setDay(currentDay)
        })

        client.on('paused', () => {
          console.log('[WorkerContext] Simulation paused')
          setRunning(false)
        })

        client.on('resumed', () => {
          console.log('[WorkerContext] Simulation resumed')
          setRunning(true)
        })

        client.on('error', (error: Error) => {
          console.error('[WorkerContext] Worker error:', error)
        })
      } catch (error) {
        console.error('[WorkerContext] Failed to create worker:', error)
      }
    }

    // Cleanup only on app unmount (not on re-render)
    return () => {
      console.log('[WorkerContext] App unmounting, destroying worker')
      if (clientRef.current) {
        clientRef.current.destroy()
        clientRef.current = null
      }
    }
  }, []) // Empty deps - only run on mount/unmount

  // Control functions
  const init = (seedValue: number, scenarioValue: ScenarioMode, speed: number) => {
    if (!clientRef.current) {
      console.error('[WorkerContext] Cannot init: no worker client')
      return
    }

    if (initialized) {
      console.warn('[WorkerContext] Already initialized')
      return
    }

    setSeed(seedValue)
    setScenario(scenarioValue)

    const interval = Math.floor(30000 / speed)
    clientRef.current.init(seedValue, scenarioValue, interval)
  }

  const start = () => {
    if (!clientRef.current) {
      console.error('[WorkerContext] Cannot start: no worker client')
      return
    }

    if (!initialized) {
      console.error('[WorkerContext] Cannot start: not initialized')
      return
    }

    clientRef.current.start()
  }

  const pause = () => {
    if (!clientRef.current) {
      console.error('[WorkerContext] Cannot pause: no worker client')
      return
    }

    clientRef.current.pause()
  }

  const step = () => {
    if (!clientRef.current) {
      console.error('[WorkerContext] Cannot step: no worker client')
      return
    }

    clientRef.current.step()
  }

  return (
    <SimulationWorkerContext.Provider
      value={{
        client: clientRef.current,
        initialized,
        running,
        month,
        day,
        scenario,
        seed,
        lastUpdate,
        init,
        start,
        pause,
        step
      }}
    >
      {children}
    </SimulationWorkerContext.Provider>
  )
}

/**
 * Hook to access the global simulation worker
 * Must be used within SimulationWorkerProvider
 */
export function useSimulationWorker() {
  const context = useContext(SimulationWorkerContext)

  if (!context) {
    throw new Error('useSimulationWorker must be used within SimulationWorkerProvider')
  }

  return context
}

/**
 * Navigation Component with Simulation Controls
 *
 * Main navigation for dashboard screens.
 * Includes simulation controls accessible from any page.
 * Supports keyboard shortcuts (1-9 for quick navigation).
 */

'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { useEffect, useState } from 'react'
import { cn } from '@/lib/utils'
import { useSimulationWorker } from '@/lib/contexts/SimulationWorkerContext'
import type { ScenarioMode } from '@/types/game'

const navItems = [
  { label: 'Overview', href: '/dashboard', shortcut: '1' },
  { label: 'Paradigms', href: '/paradigms', shortcut: '2' },
  { label: 'AI Agents', href: '/ai-agents', shortcut: '3' },
  { label: 'Crises', href: '/crises', shortcut: '4' },
  { label: 'Environment', href: '/environment', shortcut: '5' },
  { label: 'Tech Tree', href: '/tech-tree', shortcut: '6' },
  { label: 'Detection', href: '/detection', shortcut: '7' },
  { label: 'Regions', href: '/regions', shortcut: '8' },
  { label: 'Timeline', href: '/timeline', shortcut: '9' },
  { label: 'Real-Time', href: '/realtime', shortcut: '0' },
]

export function Navigation() {
  const pathname = usePathname()

  // Get shared worker state from context
  const { initialized, running, month, day, scenario, seed, init, start, pause, step } = useSimulationWorker()

  // Local UI state only
  const [showConfig, setShowConfig] = useState(false)
  const [configSeed, setConfigSeed] = useState(42000)
  const [configScenario, setConfigScenario] = useState<ScenarioMode>('historical')
  const [configSpeed, setConfigSpeed] = useState(1.0)

  // Initialize simulation
  const handleInit = () => {
    if (initialized) return

    try {
      init(configSeed, configScenario, configSpeed)
      setShowConfig(false)
    } catch (err) {
      console.error('[Navigation] Init error:', err)
    }
  }

  // Start/pause toggle
  const handleToggleRunning = () => {
    if (!initialized) return

    if (running) {
      pause()
    } else {
      start()
    }
  }

  // Manual step
  const handleStep = () => {
    if (!initialized) return
    step()
  }

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyPress = (e: KeyboardEvent) => {
      // Ignore if typing in input
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) {
        return
      }

      const key = e.key

      // Space to pause/play
      if (key === ' ') {
        e.preventDefault()
        handleToggleRunning()
        return
      }

      // Number shortcuts for navigation
      if (key === '0') {
        window.location.href = navItems[navItems.length - 1]?.href || '/realtime'
      } else {
        const num = parseInt(key)
        if (num >= 1 && num <= 9) {
          const item = navItems[num - 1]
          if (item) {
            window.location.href = item.href
          }
        }
      }
    }

    window.addEventListener('keypress', handleKeyPress)
    return () => window.removeEventListener('keypress', handleKeyPress)
  }, [handleToggleRunning])

  return (
    <>
      <nav className="fixed left-0 top-0 h-full w-64 border-r flex flex-col" style={{ borderColor: 'var(--white-10)', backgroundColor: 'var(--color-near-black)' }}>
        {/* Header */}
        <div className="p-6 border-b" style={{ borderColor: 'var(--white-10)' }}>
          <h1 className="text-lg font-semibold mb-1">Simulation Dashboard</h1>
          <p className="text-xs" style={{ color: 'var(--white-40)' }}>
            Research Tool
          </p>
        </div>

        {/* Simulation Status */}
        <div className="p-4 border-b space-y-3" style={{ borderColor: 'var(--white-10)' }}>
          {initialized ? (
            <>
              {/* Status indicators */}
              <div className="space-y-1">
                <div className="flex items-center justify-between text-xs">
                  <span style={{ color: 'var(--white-40)' }}>Status</span>
                  <span className={running ? 'text-green-400' : 'text-yellow-400'}>
                    {running ? 'RUNNING' : 'PAUSED'}
                  </span>
                </div>
                <div className="flex items-center justify-between text-xs">
                  <span style={{ color: 'var(--white-40)' }}>Month</span>
                  <span className="text-white">{month}</span>
                </div>
                <div className="flex items-center justify-between text-xs">
                  <span style={{ color: 'var(--white-40)' }}>Day</span>
                  <span className="text-white">{day}</span>
                </div>
                <div className="flex items-center justify-between text-xs">
                  <span style={{ color: 'var(--white-40)' }}>Scenario</span>
                  <span className="text-cyan-400">{scenario === 'historical' ? 'HIST' : 'UNPR'}</span>
                </div>
                <div className="flex items-center justify-between text-xs">
                  <span style={{ color: 'var(--white-40)' }}>Seed</span>
                  <span className="text-white font-mono">{seed}</span>
                </div>
              </div>

              {/* Control buttons */}
              <div className="flex gap-2">
                <button
                  onClick={handleToggleRunning}
                  className={cn(
                    "flex-1 px-3 py-1.5 text-xs font-medium rounded transition-all",
                    running
                      ? "bg-yellow-500/20 border border-yellow-400 text-yellow-400 hover:bg-yellow-400/30"
                      : "bg-green-500/20 border border-green-400 text-green-400 hover:bg-green-400/30"
                  )}
                >
                  {running ? 'PAUSE' : 'START'}
                </button>
                <button
                  onClick={handleStep}
                  disabled={running}
                  className="px-3 py-1.5 text-xs bg-white/5 border border-white/20 text-white/60 hover:bg-white/10 disabled:opacity-30 rounded"
                >
                  STEP
                </button>
              </div>
            </>
          ) : (
            <button
              onClick={() => setShowConfig(true)}
              className="w-full px-3 py-2 text-sm bg-cyan-500/20 border border-cyan-400 text-cyan-400 hover:bg-cyan-400/30 transition-all rounded"
            >
              Configure & Start
            </button>
          )}
        </div>

        {/* Nav Items */}
        <div className="flex-1 overflow-y-auto p-4 space-y-1">
          {navItems.map((item) => {
            const isActive = pathname === item.href

            return (
              <Link
                key={item.href}
                href={item.href}
                className={cn(
                  "flex items-center justify-between px-3 py-2 rounded transition-colors",
                  isActive
                    ? "glow-cyan"
                    : "hover:bg-white/5"
                )}
              >
                <span className={cn(
                  "text-sm",
                  isActive ? "text-white font-medium" : "text-white/60"
                )}>
                  {item.label}
                </span>
                <span className="text-xs" style={{ color: 'var(--white-30)' }}>
                  {item.shortcut}
                </span>
              </Link>
            )
          })}
        </div>

        {/* Footer */}
        <div className="p-4 border-t text-xs space-y-1" style={{ borderColor: 'var(--white-10)', color: 'var(--white-30)' }}>
          <div>Keyboard: 0-9 navigate</div>
          <div>Spacebar: pause/play</div>
          <div className="pt-2 border-t" style={{ borderColor: 'var(--white-10)' }}>Design: Elysium 2100s</div>
        </div>
      </nav>

      {/* Configuration Modal */}
      {showConfig && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur flex items-center justify-center z-50" onClick={() => setShowConfig(false)}>
          <div className="bg-black border border-white/20 p-8 max-w-md w-full shadow-[0_0_30px_rgba(0,240,255,0.3)]" onClick={(e) => e.stopPropagation()}>
            <h2 className="text-2xl mb-6 text-cyan-400">Initialize Simulation</h2>

            <div className="space-y-4">
              <div>
                <label className="block text-xs mb-2" style={{ color: 'var(--white-40)' }}>RNG SEED</label>
                <input
                  type="number"
                  value={configSeed}
                  onChange={(e) => setConfigSeed(parseInt(e.target.value))}
                  className="w-full bg-black border border-white/20 px-3 py-2 text-white rounded"
                />
              </div>

              <div>
                <label className="block text-xs mb-2" style={{ color: 'var(--white-40)' }}>SCENARIO MODE</label>
                <select
                  value={configScenario}
                  onChange={(e) => setConfigScenario(e.target.value as ScenarioMode)}
                  className="w-full bg-black border border-white/20 px-3 py-2 text-white rounded"
                >
                  <option value="historical">Historical (Known AI Timelines)</option>
                  <option value="unprecedented">Unprecedented (Novel Scenarios)</option>
                </select>
                <p className="text-xs mt-2" style={{ color: 'var(--white-30)' }}>
                  {configScenario === 'historical'
                    ? 'Simulation follows known AI development patterns and historical data'
                    : 'Simulation explores novel scenarios beyond historical precedent'}
                </p>
              </div>

              <div>
                <label className="block text-xs mb-2" style={{ color: 'var(--white-40)' }}>SIMULATION SPEED</label>
                <select
                  value={configSpeed.toFixed(1)}
                  onChange={(e) => setConfigSpeed(parseFloat(e.target.value))}
                  className="w-full bg-black border border-white/20 px-3 py-2 text-white rounded"
                >
                  <option value="0.5">0.5x (Slow)</option>
                  <option value="1.0">1.0x (Normal)</option>
                  <option value="2.0">2.0x (Fast)</option>
                  <option value="4.0">4.0x (Very Fast)</option>
                </select>
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  onClick={() => setShowConfig(false)}
                  className="flex-1 px-4 py-3 bg-white/5 border border-white/20 text-white/60 hover:bg-white/10 transition-all rounded"
                >
                  CANCEL
                </button>
                <button
                  onClick={handleInit}
                  className="flex-1 px-4 py-3 bg-cyan-500/20 border border-cyan-400 text-cyan-400 hover:bg-cyan-400/30 transition-all rounded"
                >
                  INITIALIZE
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

