                                ${stages[idx + 1].x} ${yStart + alignedHeight + (stages[idx + 1].total > 0 ? (stages[idx + 1].data.uncertain / stages[idx + 1].total) * (barHeight * (stages[idx + 1].total / maxTotal)) / 2 : 0) + 40 + (barHeight - (barHeight * (stages[idx + 1].total / maxTotal))) / 2}
                            `}
