                <path d="M 0 4 C 10 4, 20 4, 30 4" stroke="url(#flow-aligned)" strokeWidth="6" fill="none" opacity="0.5" />
              </svg>
              <span className="text-xs" style={{ color: 'var(--white-60)' }}>Flow connections</span>
            </div>
          </div>
        </div>
      </Panel>

      {/* Remove old grid - Sankey replaces it */}
