    <text
      x={stage.x + stage.width / 2}
      y={25}
      textAnchor="middle"
      fontSize="12"
      fill={stage.label === 'ESCAPED' ? 'rgb(255, 0, 64)' : 'rgb(160, 160, 160)'}
