                        }}
                      >
                        {stats.lifecycleWithAlignment.training.uncertain}
                      </div>
                    )}
                    {/* Misaligned */}
                    {stats.lifecycleWithAlignment.training.misaligned > 0 && (
                      <div
                        className="flex items-center justify-center text-xs font-semibold"
