      bciAdoption: 0,                    // No BCI yet (will be first adopters)
      enhancementLevel: 0.15,            // 15% enhanced (AI tools only, 2025 baseline)
    },

    // === MIDDLE CLASS PRAGMATISTS (40% / 35%) ===
    {
      id: 'middle_class_pragmatists',
