    // === WORKING CLASS SKEPTICS (35% / 25%) ===
    {
      id: 'working_class_skeptics',
      name: 'Working Class Skeptics',

      populationFraction: 0.35,  // 35% of population
      politicalPower: 0.25,      // 25% of political power (underrepresented)
