/**
 * useSimulation Hook
 *
 * React hook for loading and managing simulation data.
 */

import { useEffect } from 'react'
import { useSimulationStore } from '@/lib/stores/simulationStore'

export function useSimulation() {
  const {
    currentState,
    trajectory,
    isLoading,
    error,
    loadState,
    loadTrajectory,
    setError
  } = useSimulationStore()

  // Load current simulation state
  const loadCurrent = async () => {
    try {
      const response = await fetch('/api/simulation/current')

      if (!response.ok) {
        throw new Error('Failed to fetch simulation state')
      }

      const { data } = await response.json()

      // If data has snapshots, load as trajectory
      if (data.snapshots && data.snapshots.length > 0) {
        loadTrajectory(data.snapshots)
      } else {
        // Otherwise just load the final state
        loadState(data)
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error')
    }
  }

  // Load Monte Carlo results
  const loadMonteCarloResults = async (limit = 100) => {
    try {
      const response = await fetch(`/api/simulation/monte-carlo?limit=${limit}`)

      if (!response.ok) {
        throw new Error('Failed to fetch Monte Carlo results')
      }

      const data = await response.json()
      return data
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error')
      return null
    }
  }

  return {
    currentState,
    trajectory,
    isLoading,
    error,
    loadCurrent,
    loadMonteCarloResults
  }
}

/**
 * Hook to access the global simulation worker
 * Must be used within SimulationWorkerProvider
 */
export function useSimulationWorker() {
  const context = useContext(SimulationWorkerContext)

  if (!context) {
    throw new Error('useSimulationWorker must be used within SimulationWorkerProvider')
  }

  return context
}

  // Latest update delta (for pages that need detailed state)
  lastUpdate: StateDelta | null

  // Control functions
  init: (seed: number, scenario: ScenarioMode, speed: number, alignmentConfig?: import('@/types/alignment-dynamics').AlignmentDynamicsConfig) => void
  start: () => void
  pause: () => void
  step: () => void
}

const SimulationWorkerContext = createContext<SimulationWorkerContextValue | null>(null)

export function SimulationWorkerProvider({ children }: { children: ReactNode }) {
  // Use ref to ensure worker persists across re-renders
  const clientRef = useRef<SimulationWorkerClient | null>(null)

  // Simulation state (actual month/day in the simulation)
  const [initialized, setInitialized] = useState(false)
  const [running, setRunning] = useState(false)
  const [simulationMonth, setSimulationMonth] = useState(0)

