          label="Total Events"
          value={stats.total}
          status="normal"
        />
        <MetricCard
          label="Critical Events"
          value={stats.critical}
          status={stats.critical > 10 ? 'critical' : 'normal'}
        />
        <MetricCard
          label="Warning Events"
          value={stats.warning}
          status="normal"
        />
        <MetricCard
          label="Current Month"
          value={currentState.currentMonth || 0}
          status="normal"
        />
      </div>

      {/* Filter Controls */}
      <Panel title="Event Filters">
        <div className="flex flex-wrap gap-2">
          <button
