                  color: filterType === cat ? 'var(--color-cyan)' : 'var(--white-60)',
                }}
              >
                {cat} ({count})
              </button>
            )
          })}
        </div>
      </Panel>

      {/* Event Timeline */}
      <Panel title={`Event Log (${filteredEvents.length} events)`}>
        <div className="space-y-2">
          {filteredEvents.length === 0 && (
