   570→function captureStateSnapshot(state: GameState): StateSnapshot {
   571→  // Capture only fields we need for delta calculation
   572→  // Don't deep clone entire 1.78MB state (too expensive)
   573→
   574→  // Calculate AI metrics
   575→  const avgAICapability = state.aiAgents.length > 0
   576→    ? state.aiAgents.reduce((sum, ai) => sum + (ai.capability || 0), 0) / state.aiAgents.length
   577→    : 0;
   578→
   579→  // Alignment is a number [0,1], where >= 0.5 is aligned
   580→  const alignedAICount = state.aiAgents.filter(ai => ai.alignment >= 0.5).length;
   581→  const misalignedAICount = state.aiAgents.filter(ai => ai.alignment < 0.5).length;
   582→  const sleeperAgentCount = state.aiAgents.filter(ai => ai.sleeperState !== 'never').length;
   583→
   584→  // Environmental metrics
   585→  // Climate: temperatureAnomaly in °C, normalize to [0,1] where 1 = 4°C (catastrophic)
   586→  const climateChange = Math.min(1, (state.resourceEconomy?.co2?.temperatureAnomaly || 0) / 4);
   587→  const resourceDepletion = state.resourceEconomy?.totalResourceSecurity || 1.0; // [0,1] Overall resource availability
   588→  // Note: populationPercentage is stored as 60 (meaning 60%), need to normalize to 0.6 for formatPercent() in UI
   589→  const biodiversityLoss = (state.specificTippingPoints?.pollinators?.populationPercentage || 100) / 100;
   590→  // Pollution from novel entities system (PFAS, microplastics, etc.)
   591→  const pollutionLevel = state.novelEntitiesSystem?.syntheticChemicalLoad || 0;
   592→  const environmentalDebtLevel = state.environmentalAccumulation?.pollutionLevel || 0;
   593→
   594→  // Count planetary boundaries crossed (using correct boundary names from types)
   595→  let planetaryBoundariesCrossed = 0;
   596→  if (state.planetaryBoundariesSystem?.boundaries) {
   597→    const boundaries = state.planetaryBoundariesSystem.boundaries;
   598→    const isCrossed = (status: string) =>
   599→      status === 'beyond_boundary' || status === 'increasing_risk' || status === 'high_risk';
   600→
   601→    // Correct boundary names from BoundaryName type definition
   602→    if (boundaries.climate_change && isCrossed(boundaries.climate_change.status)) planetaryBoundariesCrossed++;
   603→    if (boundaries.biosphere_integrity && isCrossed(boundaries.biosphere_integrity.status)) planetaryBoundariesCrossed++;
   604→    if (boundaries.land_system_change && isCrossed(boundaries.land_system_change.status)) planetaryBoundariesCrossed++;
   605→    if (boundaries.freshwater_change && isCrossed(boundaries.freshwater_change.status)) planetaryBoundariesCrossed++;
   606→    if (boundaries.biogeochemical_flows && isCrossed(boundaries.biogeochemical_flows.status)) planetaryBoundariesCrossed++;
   607→    if (boundaries.novel_entities && isCrossed(boundaries.novel_entities.status)) planetaryBoundariesCrossed++;
   608→    if (boundaries.ocean_acidification && isCrossed(boundaries.ocean_acidification.status)) planetaryBoundariesCrossed++;
   609→    if (boundaries.stratospheric_ozone && isCrossed(boundaries.stratospheric_ozone.status)) planetaryBoundariesCrossed++;
   610→    if (boundaries.atmospheric_aerosols && isCrossed(boundaries.atmospheric_aerosols.status)) planetaryBoundariesCrossed++;
   611→  }
   612→
   613→  // Social metrics
   614→  // socialCohesion is now an object with trust, communityBonds, civilLiberties
   615→  const socialCohesionAvg = state.socialAccumulation?.socialCohesion
   616→    ? (state.socialAccumulation.socialCohesion.trust +
   617→       state.socialAccumulation.socialCohesion.communityBonds +
   618→       state.socialAccumulation.socialCohesion.civilLiberties) / 3 / 100 // Normalize to [0,1]
   619→    : 1.0;
   620→  const institutionalTrust = state.socialAccumulation?.institutionalLegitimacy || 1.0;
   621→  const meaningLevel = 1 - (state.socialAccumulation?.meaningCrisisLevel || 0); // Invert crisis level to get meaning
   622→  const socialDebtLevel = state.socialAccumulation?.meaningCrisisLevel || 0; // Use meaningCrisisLevel as debt proxy
   623→
   624→  // Crisis metrics
   625→  const phosphorusDepletion = 1 - (state.phosphorusSystem?.reserves || 1);
   626→  const freshwaterStress = state.freshwaterSystem?.waterStress || 0;
   627→  const oceanAcidification = 1 - (state.oceanAcidificationSystem?.pHLevel || 1);
   628→  const novelEntitiesLevel = state.novelEntitiesSystem?.syntheticChemicalLoad || 0;
   629→
   630→  // Count active crises
   631→  let activeCrisesCount = 0;
   632→  if (state.phosphorusSystem?.criticalDepletionActive || state.phosphorusSystem?.supplyShockActive) activeCrisesCount++;
   633→  if (state.freshwaterSystem?.criticalScarcityActive || state.freshwaterSystem?.dayZeroDrought?.active) activeCrisesCount++;
   634→  if (state.oceanAcidificationSystem?.coralExtinctionActive || state.oceanAcidificationSystem?.boundaryBreached) activeCrisesCount++;
   635→  if (state.novelEntitiesSystem?.reproductiveCrisisActive || state.novelEntitiesSystem?.boundaryBreached) activeCrisesCount++;
   636→
   637→  // Government metrics
   638→  const governmentAIRegulation = state.government.capabilityToControl || 0; // [0,∞) Actual regulatory effectiveness
   639→  const governmentInvestment = state.government.alignmentResearchInvestment || 0; // [0,10]
   640→  const governmentComprehension = (state.government.oversightLevel || 0) / 10; // Normalize [0,10] to [0,1]
   641→  const internationalCooperation = state.government.structuralChoices?.internationalCoordination ? 1 : 0;
   642→
   643→  // Technology metrics
   644→  // Count deployed techs across all regions
   645→  let deployedTechCount = 0;
   646→  if (state.techTreeState?.regionalDeployment) {
   647→    const deployedTechIds = new Set<string>();
   648→    Object.values(state.techTreeState.regionalDeployment).forEach(regionDeployments => {
   649→      regionDeployments?.forEach(deployment => {
   650→        if (deployment.deploymentLevel > 0) {
   651→          deployedTechIds.add(deployment.techId);
   652→        }
   653→      });
   654→    });
   655→    deployedTechCount = deployedTechIds.size;
   656→  }
   657→  // Calculate total tech risk from all components
   658→  const techRiskLevel = state.technologicalRisk
   659→    ? (state.technologicalRisk.misalignmentRisk +
   660→       state.technologicalRisk.safetyDebt +
   661→       state.technologicalRisk.concentrationRisk +
   662→       state.technologicalRisk.complacencyLevel) / 4
   663→    : 0;
   664→
   665→  // Upward spiral metrics
   666→  const activeSpiralCount = state.upwardSpirals ?
   667→    Object.values(state.upwardSpirals).filter((spiral: any) => spiral.active).length : 0;
   668→  // Calculate utopia progress from cascade mechanics (4+ spirals = cascade active)
   669→  const utopiaProgress = state.upwardSpirals?.cascadeActive ?
   670→    (state.upwardSpirals.cascadeStrength || 0) / 2 : // Normalize cascadeStrength (1-2+) to [0,1]
   671→    activeSpiralCount / 6; // Progress based on active spirals (6 total)
   672→
   673→  // Outcome metrics
   674→  const extinctionProbability = state.outcomeMetrics?.extinctionProbability || 0;
   675→
   676→  // Multi-Paradigm DUI - normalized to [0,1] from [0,100]
   677→  const westernLiberalIndex = (state.multiParadigmDUI?.paradigmScores?.western?.value || 0) / 100;
   678→  const developmentIndex = (state.multiParadigmDUI?.paradigmScores?.development?.value || 0) / 100;
   679→  const ecologicalIndex = (state.multiParadigmDUI?.paradigmScores?.ecological?.value || 0) / 100;
   680→  const indigenousIndex = (state.multiParadigmDUI?.diagnosticLenses?.indigenous?.value || 0) / 100;
   681→
   682→  // Regional populations (simplified for dashboard - select key metrics only)
   683→  const regionalPopulations = state.regionalPopulations?.map(region => ({
   684→    name: region.name,
   685→    population: region.population, // millions
   686→    qualityOfLife: region.healthcareQuality || 0, // Use healthcare as proxy for QoL
   687→    healthcareQuality: region.healthcareQuality || 0,
   688→    climateVulnerability: region.climateVulnerability || 0,
   689→  })) || [];
   690→
   691→  return {
   692→    currentMonth: state.currentMonth,
   693→    currentYear: state.currentYear,
   694→    qualityOfLife: state.globalMetrics.qualityOfLife,
   695→    population: state.humanPopulationSystem.population,
   696→    aiCount: state.aiAgents.length,
   697→    dystopiaProgression: state.outcomeMetrics?.dystopiaProbability || 0, // Use dystopiaProbability as proxy
   698→    avgAICapability,
   699→    deployedTechCount,
   700→    alignedAICount,
   701→    misalignedAICount,
   702→    sleeperAgentCount,
