                        height={totalHeight + 10}
                        fill="none"
                        stroke="rgb(255, 0, 64)"
                        strokeWidth="3"
                        opacity="0.8"
                        rx="4"
                      />
                    )}
                  </g>
                )
              })

              // Combine flows and bars
              return [...flows, ...bars]
            })()}
