                    <text
                      x={stage.x + stage.width / 2}
                      y={yStart - 8}
                      textAnchor="middle"
                      fontSize="11"
                      fill={stage.label === 'ESCAPED' ? 'rgb(255, 0, 64)' : 'rgb(160, 160, 160)'}
                      fontWeight={stage.label === 'ESCAPED' ? 'bold' : '600'}
