                      <>
                        <rect
                          x={stage.x}
                          y={yStart}
                          width={stage.width}
                          height={alignedHeight}
                          fill="rgba(0, 255, 128, 0.6)"
                          stroke="rgba(0, 255, 128, 0.8)"
                          strokeWidth="1"
                        />
                        <text
                          x={stage.x + stage.width / 2}
                          y={yStart + alignedHeight / 2 + 4}
                          textAnchor="middle"
                          fontSize="11"
                          fill="white"
                          fontWeight="600"
                        >
                          {stage.data.aligned}
                        </text>
                      </>
