     1→# Web Worker Dual-Mode Architecture
     2→
     3→**Date:** October 22, 2025
     4→**Status:** Design Phase
     5→**Objective:** Enable simulation to run in both Node.js (Monte Carlo) and browser (real-time) without code duplication
     6→
     7→## Problem Statement
     8→
     9→Current state:
    10→- ✅ Simulation engine works in Node.js for Monte Carlo
    11→- ❌ Cannot run in browser for real-time playable mode
    12→- ❌ No player interaction during simulation
    13→
    14→Requirement:
    15→- Same simulation engine code runs in **both** Node.js and browser
    16→- No code duplication
    17→- Monte Carlo continues to work unchanged
    18→- Real-time mode runs in Web Worker (non-blocking UI)
    19→
    20→## Architecture Overview
    21→
    22→```
    23→┌─────────────────────────────────────────────────────────────┐
    24→│                    Simulation Engine (Pure TS)              │
    25→│  src/simulation/engine.ts, initialization.ts, phases/*      │
    26→│  - Framework-agnostic                                       │
    27→│  - No Node.js or browser-specific APIs                     │
    28→│  - Deterministic RNG                                        │
    29→└─────────────────────────────────────────────────────────────┘
    30→                           ▲
    31→                           │
    32→        ┌──────────────────┴──────────────────┐
    33→        │                                     │
    34→┌───────▼─────────┐              ┌───────────▼─────────────┐
    35→│   Node.js Mode  │              │    Browser Mode         │
    36→│   (Monte Carlo) │              │   (Real-time Playable)  │
    37→└─────────────────┘              └─────────────────────────┘
    38→        │                                     │
    39→        │                                     │
    40→┌───────▼──────────┐             ┌───────────▼──────────────┐
    41→│ scripts/         │             │ Main Thread (UI)         │
    42→│ monteCarloSim.ts │             │   - Dashboard            │
    43→│                  │             │   - Player controls      │
    44→│ - Direct import  │             │   - State visualization  │
    45→│ - Headless run   │             │                          │
    46→│ - File output    │             │ postMessage              │
    47→└──────────────────┘             │     ▼        ▲           │
    48→                                 │ Web Worker   │           │
    49→                                 │   - Imports engine       │
    50→                                 │   - Runs simulation      │
    51→                                 │   - Sends delta updates  │
    52→                                 └──────────────────────────┘
    53→```
    54→
    55→## Design Principles
    56→
    57→1. **Single Source of Truth:** `src/simulation/` is the only simulation code
    58→2. **Environment Abstraction:** Engine doesn't know if it's in Node.js or browser
    59→3. **Message Passing:** Web Worker communicates via structured messages
    60→4. **Delta Updates:** Only send changed state to UI (not full 1.78MB state)
    61→5. **Non-Breaking:** Monte Carlo scripts continue to work unchanged
    62→
    63→## Implementation Plan
    64→
    65→### Part 1: Create Web Worker Wrapper (2-3 hours)
    66→
    67→**File:** `src/workers/simulationWorker.ts`
    68→
    69→```typescript
    70→import { SimulationEngine } from '../simulation/engine';
    71→import { createDefaultInitialState } from '../simulation/initialization';
    72→import type { GameState } from '../types/game';
    73→
    74→// Worker state
    75→let engine: SimulationEngine | null = null;
    76→let state: GameState | null = null;
    77→let running = false;
    78→let intervalId: number | null = null;
    79→
    80→// Message types
    81→type WorkerMessage =
    82→  | { type: 'init'; seed: number; scenario: 'historical' | 'unprecedented' }
    83→  | { type: 'start' }
    84→  | { type: 'pause' }
    85→  | { type: 'resume' }
    86→  | { type: 'step' }
    87→  | { type: 'decision'; decision: PlayerDecision };
    88→
    89→type WorkerResponse =
    90→  | { type: 'initialized'; state: GameState }
    91→  | { type: 'update'; delta: StateDelta; month: number }
    92→  | { type: 'paused' }
    93→  | { type: 'resumed' }
    94→  | { type: 'error'; error: string };
    95→
    96→// Listen for messages from main thread
    97→self.addEventListener('message', (event: MessageEvent<WorkerMessage>) => {
    98→  const msg = event.data;
    99→
   100→  try {
   101→    switch (msg.type) {
   102→      case 'init':
   103→        engine = new SimulationEngine({ seed: msg.seed });
   104→        state = createDefaultInitialState(msg.scenario);
   105→        self.postMessage({ type: 'initialized', state } as WorkerResponse);
   106→        break;
   107→
   108→      case 'start':
   109→        if (!engine || !state) throw new Error('Not initialized');
   110→        running = true;
   111→        startSimulationLoop();
   112→        break;
   113→
   114→      case 'pause':
   115→        running = false;
   116→        if (intervalId !== null) {
   117→          clearInterval(intervalId);
   118→          intervalId = null;
   119→        }
   120→        self.postMessage({ type: 'paused' } as WorkerResponse);
   121→        break;
   122→
   123→      case 'resume':
   124→        if (!running) {
   125→          running = true;
   126→          startSimulationLoop();
   127→          self.postMessage({ type: 'resumed' } as WorkerResponse);
   128→        }
   129→        break;
   130→
   131→      case 'step':
   132→        if (!engine || !state) throw new Error('Not initialized');
   133→        performStep();
   134→        break;
   135→
   136→      case 'decision':
   137→        if (!state) throw new Error('Not initialized');
   138→        // Inject player decision (Phase 3)
   139→        injectPlayerDecision(state, msg.decision);
   140→        break;
   141→    }
   142→  } catch (error) {
   143→    self.postMessage({
   144→      type: 'error',
   145→      error: error instanceof Error ? error.message : String(error)
   146→    } as WorkerResponse);
   147→  }
   148→});
   149→
   150→function startSimulationLoop() {
   151→  // Run at 1 day/second (1000ms interval)
   152→  intervalId = setInterval(() => {
   153→    if (!running || !engine || !state) {
   154→      if (intervalId !== null) {
   155→        clearInterval(intervalId);
   156→        intervalId = null;
   157→      }
   158→      return;
   159→    }
   160→
   161→    performStep();
   162→  }, 1000) as unknown as number;
   163→}
   164→
   165→function performStep() {
   166→  if (!engine || !state) return;
   167→
   168→  const previousState = cloneForDelta(state);
   169→
   170→  // Run one simulation step
   171→  engine.step(state);
   172→
   173→  // Calculate delta (only changed fields)
   174→  const delta = calculateDelta(previousState, state);
   175→
   176→  // Send update to main thread
   177→  self.postMessage({
   178→    type: 'update',
   179→    delta,
   180→    month: state.currentMonth
   181→  } as WorkerResponse);
   182→}
   183→
   184→function calculateDelta(previous: GameState, current: GameState): StateDelta {
   185→  // Only send changed fields (avoids 1.78MB full state)
   186→  const delta: StateDelta = {};
   187→
   188→  // Check top-level fields
   189→  if (previous.currentMonth !== current.currentMonth) {
   190→    delta.currentMonth = current.currentMonth;
   191→  }
   192→
   193→  if (previous.globalMetrics.qualityOfLife !== current.globalMetrics.qualityOfLife) {
   194→    delta.qualityOfLife = current.globalMetrics.qualityOfLife;
   195→  }
   196→
   197→  // Add other changed fields as needed
   198→  // This is where optimization happens - only send what changed
   199→
   200→  return delta;
   201→}
   202→
   203→function cloneForDelta(state: GameState): GameState {
   204→  // Shallow clone of fields we need to compare
   205→  // Don't deep clone entire 1.78MB state (too expensive)
   206→  return {
   207→    currentMonth: state.currentMonth,
   208→    globalMetrics: { ...state.globalMetrics },
   209→    // Add other fields we want to track changes for
   210→  } as GameState;
   211→}
   212→
   213→function injectPlayerDecision(state: GameState, decision: PlayerDecision) {
   214→  // Player decision injection (Phase 3)
   215→  // For now, placeholder
   216→  console.log('Player decision:', decision);
   217→}
   218→
   219→// Types
   220→interface PlayerDecision {
   221→  type: 'policy' | 'investment' | 'emergency';
   222→  data: any;
   223→}
   224→
   225→interface StateDelta {
   226→  currentMonth?: number;
   227→  qualityOfLife?: number;
   228→  // Add other fields that can change
   229→}
   230→```
   231→
   232→### Part 2: Main Thread Interface (1-2 hours)
   233→
   234→**File:** `src/lib/simulationWorkerClient.ts`
   235→
   236→```typescript
   237→import type { GameState } from '@/types/game';
   238→
   239→export class SimulationWorkerClient {
   240→  private worker: Worker | null = null;
   241→  private callbacks: Map<string, Set<Function>> = new Map();
   242→
   243→  constructor() {
   244→    // Initialize Web Worker (browser only)
   245→    if (typeof window !== 'undefined') {
   246→      this.worker = new Worker(
   247→        new URL('../workers/simulationWorker.ts', import.meta.url),
   248→        { type: 'module' }
   249→      );
   250→
   251→      this.worker.addEventListener('message', this.handleMessage.bind(this));
   252→    }
   253→  }
   254→
   255→  private handleMessage(event: MessageEvent) {
   256→    const msg = event.data;
   257→
   258→    switch (msg.type) {
   259→      case 'initialized':
   260→        this.emit('initialized', msg.state);
   261→        break;
   262→      case 'update':
   263→        this.emit('update', msg.delta, msg.month);
   264→        break;
   265→      case 'paused':
   266→        this.emit('paused');
   267→        break;
   268→      case 'resumed':
   269→        this.emit('resumed');
   270→        break;
   271→      case 'error':
   272→        this.emit('error', msg.error);
   273→        break;
   274→    }
   275→  }
   276→
   277→  // Event emitter pattern
   278→  on(event: string, callback: Function) {
   279→    if (!this.callbacks.has(event)) {
   280→      this.callbacks.set(event, new Set());
   281→    }
   282→    this.callbacks.get(event)!.add(callback);
   283→  }
   284→
   285→  off(event: string, callback: Function) {
   286→    this.callbacks.get(event)?.delete(callback);
   287→  }
   288→
   289→  private emit(event: string, ...args: any[]) {
   290→    this.callbacks.get(event)?.forEach(cb => cb(...args));
   291→  }
   292→
   293→  // Public API
   294→  init(seed: number, scenario: 'historical' | 'unprecedented' = 'historical') {
   295→    this.worker?.postMessage({ type: 'init', seed, scenario });
   296→  }
   297→
   298→  start() {
   299→    this.worker?.postMessage({ type: 'start' });
   300→  }
   301→
   302→  pause() {
   303→    this.worker?.postMessage({ type: 'pause' });
   304→  }
   305→
   306→  resume() {
   307→    this.worker?.postMessage({ type: 'resume' });
   308→  }
   309→
   310→  step() {
   311→    this.worker?.postMessage({ type: 'step' });
   312→  }
   313→
   314→  decision(decision: any) {
   315→    this.worker?.postMessage({ type: 'decision', decision });
   316→  }
   317→
   318→  destroy() {
   319→    this.worker?.terminate();
   320→    this.worker = null;
   321→    this.callbacks.clear();
   322→  }
   323→}
   324→```
